CREATE TABLE IF NOT EXISTS mall_product (id BIGINT NOT NULL AUTO_INCREMENT, product_code VARCHAR(64) NOT NULL, name VARCHAR(200) NOT NULL, description TEXT NULL, main_image VARCHAR(500) NULL, price DECIMAL(19,2) NOT NULL, stock INT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'OFF_SHELF', create_by VARCHAR(64) NULL, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_by VARCHAR(64) NULL, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY uk_mall_product_code(product_code), KEY idx_mall_product_status(status), CONSTRAINT chk_mall_product_price CHECK(price>0), CONSTRAINT chk_mall_product_stock CHECK(stock>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商城商品';